def calculate_S(N):
    S = 0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            S += (a * b) // (N + 1)
    return S

def target_T(N):
    return (N**3 - N**2 + 2) / 4

results = {}
for N in [1, 2, 3, 4, 5]:
    S_val = calculate_S(N)
    T_val = target_T(N)
    results[N] = (S_val, T_val)

print("N | S (Calculated Sum) | T(N) (Target Expression)")
for N, (S_val, T_val) in results.items():
    print(f"{N} | {S_val} | {T_val}")

# Verification check
matches = True
for N, (S_val, T_val) in results.items():
    if S_val != T_val:
        matches = False

print(f"\nDo all sums match the target expression? {matches}")

